"use client";

/* ─────────────────────────────────────────────────────────
 * IMAGE COMPARE: two pictures, one divide
 *
 *   drag     press anywhere and the divide is thrown to your
 *            finger, then follows it exactly
 *   reveal   the "after" picture sits in a window that slides one
 *            way while the picture inside slides back the other:
 *            two moving layers, nothing repainted while you drag
 *   labels   each side's label fades as its picture runs out
 *   keys     arrows by 1%, Shift by 10%, Home and End; a
 *            double-click brings the divide home to the middle
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { ChevronsLeftRight, ImageOff } from "lucide-react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { TextMorph } from "./text-morph";

export type CompareImage = { src: string; alt: string; className?: string };
export interface ImageCompareProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  before: CompareImage;
  after: CompareImage;
  beforeLabel?: string;
  afterLabel?: string;
  label?: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  onValueCommit?: (value: number) => void;
  aspectRatio?: number;
}
const clamp = (value: number) =>
  Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 50;

function Picture({ image }: { image: CompareImage }) {
  const [failed, setFailed] = React.useState(false);
  return failed ? (
    <div
      role="img"
      aria-label={`${image.alt} (unavailable)`}
      className="flex size-full items-center justify-center bg-muted text-muted-foreground"
    >
      <ImageOff className="size-6" aria-hidden="true" />
    </div>
  ) : (
    <img
      src={image.src}
      alt={image.alt}
      draggable={false}
      decoding="async"
      onError={() => setFailed(true)}
      className={`size-full select-none object-cover ${image.className ?? ""}`}
    />
  );
}

// The same strings are written by React and by the gesture, so either can take over from the other.
const windowAt = (p: number) => `translate3d(${p - 100}%,0,0)`;
const pictureAt = (p: number) => `translate3d(${100 - p}%,0,0)`;
const lineAt = (p: number) => `translate3d(${p}%,0,0)`;
const handleAt = (p: number) =>
  `translate3d(clamp(22px, ${p}%, calc(100% - 22px)),0,0)`;

export function ImageCompare({
  before,
  after,
  beforeLabel = "Before",
  afterLabel = "After",
  label = "Image comparison",
  value,
  defaultValue = 50,
  onValueChange,
  onValueCommit,
  aspectRatio = 1.6,
  className = "",
  ...props
}: ImageCompareProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(clamp(defaultValue));
  const position = clamp(value ?? own);
  const frame = React.useRef<HTMLDivElement>(null);
  const win = React.useRef<HTMLDivElement>(null);
  const picture = React.useRef<HTMLDivElement>(null);
  const line = React.useRef<HTMLDivElement>(null);
  const rail = React.useRef<HTMLDivElement>(null);
  const handle = React.useRef<HTMLButtonElement>(null);
  const afterTag = React.useRef<HTMLSpanElement>(null);
  const beforeTag = React.useRef<HTMLSpanElement>(null);
  const gesture = React.useRef<{
    id: number;
    origin: number;
    last: number;
    left: number;
    width: number;
    moved: boolean;
  } | null>(null);
  const hintId = React.useId();

  const motion = (on: boolean) => {
    const t = on && !reduced ? `transform 420ms ${EASE_OUT}` : "none";
    for (const el of [win.current, picture.current, line.current, rail.current])
      if (el) el.style.transition = t;
  };
  const paint = (p: number) => {
    if (win.current) win.current.style.transform = windowAt(p);
    if (picture.current) picture.current.style.transform = pictureAt(p);
    if (line.current) line.current.style.transform = lineAt(p);
    if (rail.current) rail.current.style.transform = handleAt(p);
    if (afterTag.current) afterTag.current.style.opacity = p > 12 ? "1" : "0";
    if (beforeTag.current) beforeTag.current.style.opacity = p < 88 ? "1" : "0";
    handle.current?.setAttribute("aria-valuenow", String(Math.round(p)));
    handle.current?.setAttribute(
      "aria-valuetext",
      `${Math.round(p)}% ${afterLabel}`,
    );
  };
  /** Settle on a value: React state, the parent, and an eased move when it wasn't under the finger. */
  const go = (next: number, animate: boolean, commit = true) => {
    const p = clamp(next);
    motion(animate);
    paint(p);
    if (value === undefined) setOwn(p);
    onValueChange?.(p);
    if (commit) onValueCommit?.(p);
    return p;
  };

  // A controlled value that changes from outside eases there.
  React.useLayoutEffect(() => {
    if (gesture.current) return;
    motion(true);
    paint(position);
  }, [position]);

  const finish = (event: React.PointerEvent, cancelled = false) => {
    const state = gesture.current;
    if (!state || event.pointerId !== state.id) return;
    gesture.current = null;
    // A release near the middle snaps home.
    const next = cancelled
      ? state.origin
      : Math.abs(state.last - 50) < 3
        ? 50
        : state.last;
    go(next, cancelled || next !== state.last || !state.moved, !cancelled);
  };

  return (
    <div
      {...props}
      role="region"
      aria-label={label}
      className={`w-full text-foreground ${className}`}
    >
      <div
        ref={frame}
        className="relative isolate cursor-ew-resize overflow-clip rounded-[20px] border border-border bg-muted"
        style={{
          aspectRatio: Math.max(0.25, aspectRatio),
          touchAction: "pan-y",
        }}
        onPointerDown={(event) => {
          if (event.button !== 0 || !event.isPrimary) return;
          // Keep the handle focused: the mousedown that follows would otherwise move focus to the page.
          event.preventDefault();
          const rect = event.currentTarget.getBoundingClientRect();
          event.currentTarget.setPointerCapture(event.pointerId);
          // Focus follows the press so the arrow keys work next, without a keyboard focus ring after a mouse drag.
          handle.current?.focus({
            preventScroll: true,
            focusVisible: false,
          } as FocusOptions);
          const p = clamp(
            ((event.clientX - rect.left) / Math.max(1, rect.width)) * 100,
          );
          gesture.current = {
            id: event.pointerId,
            origin: position,
            last: p,
            left: rect.left,
            width: Math.max(1, rect.width),
            moved: false,
          };
          // Thrown to the finger, then attached to it.
          motion(true);
          paint(p);
        }}
        onPointerMove={(event) => {
          const state = gesture.current;
          if (!state || state.id !== event.pointerId) return;
          if (!state.moved) {
            state.moved = true;
            motion(false);
          }
          state.last = clamp(
            ((event.clientX - state.left) / state.width) * 100,
          );
          paint(state.last);
          onValueChange?.(state.last);
        }}
        onDoubleClick={() => go(50, true)}
        onPointerUp={(event) => finish(event)}
        onPointerCancel={(event) => finish(event, true)}
        onLostPointerCapture={(event) => finish(event, true)}
      >
        <div className="absolute inset-0">
          <Picture key={before.src} image={before} />
        </div>
        <div
          ref={win}
          className="absolute inset-0 overflow-hidden will-change-transform"
          style={{ transform: windowAt(position) }}
        >
          <div
            ref={picture}
            className="absolute inset-0 will-change-transform"
            style={{ transform: pictureAt(position) }}
          >
            <Picture key={after.src} image={after} />
          </div>
        </div>
        <div
          ref={line}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 will-change-transform"
          style={{ transform: lineAt(position) }}
        >
          <span className="absolute inset-y-0 left-0 w-px -translate-x-1/2 bg-background" />
        </div>
        <div
          ref={rail}
          className="pointer-events-none absolute inset-0 will-change-transform"
          style={{ transform: handleAt(position) }}
        >
          <button
            ref={handle}
            type="button"
            role="slider"
            aria-label={label}
            aria-describedby={hintId}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(position)}
            aria-valuetext={`${Math.round(position)}% ${afterLabel}`}
            aria-orientation="horizontal"
            onKeyDown={(event) => {
              if (
                ![
                  "ArrowLeft",
                  "ArrowRight",
                  "ArrowUp",
                  "ArrowDown",
                  "Home",
                  "End",
                ].includes(event.key)
              )
                return;
              event.preventDefault();
              const step =
                (event.key === "ArrowRight" || event.key === "ArrowUp"
                  ? 1
                  : -1) * (event.shiftKey ? 10 : 1);
              go(
                event.key === "Home"
                  ? 0
                  : event.key === "End"
                    ? 100
                    : position + step,
                true,
              );
            }}
            className={`pointer-events-auto absolute left-0 top-1/2 flex size-10 -translate-x-1/2 -translate-y-1/2 cursor-ew-resize items-center justify-center rounded-full border border-border bg-background text-foreground ${INTERACTION_FOCUS}`}
          >
            <ChevronsLeftRight className="size-4" aria-hidden="true" />
          </button>
        </div>
        <span
          ref={afterTag}
          className="pointer-events-none absolute bottom-3 left-3 rounded-full border border-border bg-background px-3 py-1.5 text-[10px] font-medium transition-opacity duration-300 motion-reduce:transition-none"
          style={{ opacity: position > 12 ? 1 : 0 }}
        >
          <TextMorph>{afterLabel}</TextMorph>
        </span>
        <span
          ref={beforeTag}
          className="pointer-events-none absolute bottom-3 right-3 rounded-full border border-border bg-background px-3 py-1.5 text-[10px] font-medium transition-opacity duration-300 motion-reduce:transition-none"
          style={{ opacity: position < 88 ? 1 : 0 }}
        >
          <TextMorph>{beforeLabel}</TextMorph>
        </span>
      </div>
      <p id={hintId} className="sr-only">
        Drag to compare. Arrow keys adjust by one percent, Shift and arrows by
        ten. Home and End reveal either image. Double-click to centre.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

